import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"Panduan Instalasi","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":null}'),s={name:"guide/installation.md"};function r(o,a,l,d,u,p){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="panduan-instalasi" tabindex="-1">Panduan Instalasi <a class="header-anchor" href="#panduan-instalasi" aria-label="Permalink to &quot;Panduan Instalasi&quot;">​</a></h1><p>Untuk menjalankan <strong>Zhuxe Asistance</strong>, pastikan sistem Anda memenuhi persyaratan minimum berikut.</p><h2 id="persyaratan-sistem" tabindex="-1">Persyaratan Sistem <a class="header-anchor" href="#persyaratan-sistem" aria-label="Permalink to &quot;Persyaratan Sistem&quot;">​</a></h2><ul><li><strong>Node.js</strong>: Versi 20.9.0 atau yang lebih baru.</li><li><strong>Package Manager</strong>: <code>npm</code>, <code>pnpm</code>, atau <code>yarn</code>.</li><li><strong>Sistem Operasi</strong>: Linux (Ubuntu/Debian sangat direkomendasikan untuk VPS), macOS, atau Windows (via WSL).</li></ul><h2 id="_1-instalasi-package-inti" tabindex="-1">1. Instalasi Package Inti <a class="header-anchor" href="#_1-instalasi-package-inti" aria-label="Permalink to &quot;1. Instalasi Package Inti&quot;">​</a></h2><p>Buka terminal server Anda, buat folder proyek baru, dan inisialisasi:</p><pre><code>mkdir bot-zhuxe-saya
cd bot-zhuxe-saya
npm init -y
</code></pre><p>Setelah itu, pasang library utama Zhuxe:</p><pre><code>npm install zhuxe-assistance
</code></pre><h2 id="_2-instalasi-database-sangat-direkomendasikan" tabindex="-1">2. Instalasi Database (Sangat Direkomendasikan) <a class="header-anchor" href="#_2-instalasi-database-sangat-direkomendasikan" aria-label="Permalink to &quot;2. Instalasi Database (Sangat Direkomendasikan)&quot;">​</a></h2><p>Secara default, Zhuxe akan menyimpan sesi di memori (akan hilang jika bot di-restart). Agar bot Anda tetap <em>login</em> (tidak perlu scan ulang), Anda wajib menggunakan database.</p><p>Contoh menggunakan SQLite (ringan dan tidak butuh server database terpisah):</p><pre><code>npm install @zhuxe-js/store-sqlite better-sqlite3
</code></pre><h2 id="_3-instalasi-fitur-tambahan-opsional" tabindex="-1">3. Instalasi Fitur Tambahan (Opsional) <a class="header-anchor" href="#_3-instalasi-fitur-tambahan-opsional" aria-label="Permalink to &quot;3. Instalasi Fitur Tambahan (Opsional)&quot;">​</a></h2><p>Jika Anda ingin bot bisa memproses gambar, membuat stiker, atau mengirim pesan suara, pasang modul media:</p><pre><code>npm install @zhuxe-js/media-utils sharp
</code></pre><h2 id="troubleshooting-jika-gagal" tabindex="-1">Troubleshooting (Jika Gagal) <a class="header-anchor" href="#troubleshooting-jika-gagal" aria-label="Permalink to &quot;Troubleshooting (Jika Gagal)&quot;">​</a></h2><p>Jika saat <code>npm install</code> Anda melihat error terkait <code>node-gyp</code> atau <code>python</code>, pastikan server Anda memiliki <em>build tools</em>:</p><pre><code>sudo apt update
sudo apt install -y build-essential python3
</code></pre>`,19)])])}const c=e(s,[["render",r]]);export{h as __pageData,c as default};
